#include <algorithm>
#include <fstream>
#include <numeric>
#include <vector>
struct Edge {int u,v,weight;};
struct Query {int threshold,vertex,index;};
int main() {
    std::ifstream in("mootube.in");std::ofstream out("mootube.out");int n,q;in >> n >> q;
    std::vector<Edge> edges(n-1);for(auto& e:edges){in >> e.u >> e.v >> e.weight;--e.u;--e.v;}
    std::vector<Query> queries(q);for(int i=0;i<q;++i){in >> queries[i].threshold >> queries[i].vertex;--queries[i].vertex;queries[i].index=i;}
    std::sort(edges.begin(),edges.end(),[](const Edge& a,const Edge& b){return a.weight>b.weight;});
    std::sort(queries.begin(),queries.end(),[](const Query& a,const Query& b){return a.threshold>b.threshold;});
    std::vector<int> parent(n),size(n,1),answer(q);std::iota(parent.begin(),parent.end(),0);
    auto find=[&](int u){while(parent[u]!=u){parent[u]=parent[parent[u]];u=parent[u];}return u;};
    std::size_t next=0;
    for(const auto& query:queries){
        while(next<edges.size() && edges[next].weight>=query.threshold){int u=find(edges[next].u),v=find(edges[next].v);if(u!=v){if(size[u]<size[v]) std::swap(u,v);parent[v]=u;size[u]+=size[v];}++next;}
        answer[query.index]=size[find(query.vertex)]-1;
    }
    for(int value:answer) out << value << '\n';
}
