    std::vector<std::vector<int>> edges(n);for(int i=0;i<n-1;++i){int u,v;in >> u >> v;--u;--v;edges[u].push_back(v);edges[v].push_back(u);}
    std::vector<int> nearest(n,-1);std::queue<int> pending;
    for(int u=0;u<n;++u) if(edges[u].size()==1){nearest[u]=0;pending.push(u);}
    while(!pending.empty()){int u=pending.front();pending.pop();for(int v:edges[u]) if(nearest[v]==-1){nearest[v]=nearest[u]+1;pending.push(v);}}
    std::vector<int> parent(n,-1),depth(n,0),order{start};parent[start]=start;int farmers=0;
    for(std::size_t i=0;i<order.size();++i){int u=order[i];if(nearest[u]<=depth[u]){++farmers;continue;}for(int v:edges[u]) if(v!=parent[u]){parent[v]=u;depth[v]=depth[u]+1;order.push_back(v);}}
    out << farmers << '\n';
}
